export type Resource={title:string;url:string;type:'Watch'|'Read'|'Practice';free?:boolean}
export type Lesson={id:string;title:string;tag:string;why:string;learn:string;practice:string;build:string;criteria:string;resources:Resource[]}
export type Stage={id:string;title:string;subtitle:string;lessons:Lesson[]}
const k=(title:string,url:string,type:Resource['type']='Read'):Resource=>({title,url,type,free:true})
export const stages:Stage[]=[
{id:'foundation',title:'01 · The Editor’s Brain',subtitle:'Learn how editing creates meaning before touching effects',lessons:[
{id:'f1',title:'The editor’s job',tag:'Concept',why:'Editors control what the audience sees, hears, feels, and understands.',learn:'Study the difference between assembling footage and shaping a story.',practice:'STEP 1: Gather 10 short clips with different actions or people. STEP 2: Write three possible stories using the same clips. STEP 3: Pick one story and arrange only 6–8 clips into a 20–30 second sequence. STEP 4: Watch once with sound and once muted. STEP 5: Write one sentence explaining what each shot contributes. PASS CHECK: every shot has a story reason, not just visual appeal.',build:'Create a 30-second sequence using only cuts.',criteria:'You can explain why every shot is present.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Cuts & Transitions 101','https://www.youtube.com/watch?v=OAH0MoAv2CI','Watch'),k('Editing chapter — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'f2',title:'Shot language',tag:'Concept',why:'Shot size, angle, movement, and composition communicate information.',learn:'Learn wide, medium, close-up, inserts, reaction shots, and establishing shots.',practice:'STEP 1: Choose one simple action such as making coffee or opening a laptop. STEP 2: Collect or shoot a wide, medium, close-up, insert, reaction/detail, and establishing shot. STEP 3: Label the purpose of every shot. STEP 4: Build two versions of the action: one with only wide/medium shots and one with varied shot sizes. STEP 5: Compare clarity and emphasis. PASS CHECK: each shot size has a clear job.',build:'Shoot or collect five shot types for one simple action.',criteria:'You can choose a shot because of its purpose, not because it looks cool.',resources:[k('Joel & Ethan Coen — Shot | Reverse Shot','https://www.youtube.com/watch?v=5UE3jz_O_EM','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'f3',title:'Why do we cut?',tag:'Concept',why:'A cut should change information, emotion, time, space, or attention.',learn:'Study motivated cuts and invisible vs noticeable editing.',practice:'STEP 1: Pick a 30–60 second scene with clear cuts. STEP 2: Pause one second before every cut and predict why the editor cuts there. STEP 3: Label each cut as information, emotion, movement, time, space, or attention. STEP 4: Rebuild 15–20 seconds of the scene with your own cut choices. STEP 5: Deliberately make one version invisible and one version noticeable. PASS CHECK: you can defend every cut in both versions.',build:'Re-edit the same footage two ways: invisible and intentionally noticeable.',criteria:'You can name the reason for a cut.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Cuts & Transitions 101','https://www.youtube.com/watch?v=OAH0MoAv2CI','Watch'),k('The Kuleshov Effect','https://www.youtube.com/watch?v=Vy2Vhnqtu8I','Watch')]},
{id:'f4',title:'Continuity',tag:'Craft',why:'Continuity keeps viewers oriented so story attention is not wasted.',learn:'Learn screen direction, eyelines, match cuts, action continuity, and the 180-degree rule.',practice:'STEP 1: Use two people or two subjects facing each other. STEP 2: Collect wide, over-the-shoulder, and close-up shots while keeping screen direction consistent. STEP 3: Make a rough dialogue sequence. STEP 4: Break the 180-degree rule once on purpose. STEP 5: Compare the correct and incorrect versions and describe the confusion caused. PASS CHECK: the correct version remains spatially clear without explanation.',build:'Make a 30-second continuity scene.',criteria:'Your viewer can understand who is where without explanation.',resources:[k('Joel & Ethan Coen — Shot | Reverse Shot','https://www.youtube.com/watch?v=5UE3jz_O_EM','Watch'),k('Cuts & Transitions 101','https://www.youtube.com/watch?v=OAH0MoAv2CI','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'f5',title:'Pacing and rhythm',tag:'Craft',why:'Pacing is not simply fast cuts; it is the timing of information and emotion.',learn:'Study shot duration, acceleration, deceleration, pauses, and rhythm.',practice:'STEP 1: Build one 20–30 second sequence from the same footage. STEP 2: Version A uses longer shots and pauses. STEP 3: Version B uses shorter shots and faster transitions. STEP 4: Version C places the longest pause immediately before the important moment. STEP 5: Watch all three without looking at the timeline and write the emotion each creates. PASS CHECK: the three versions feel meaningfully different without changing the story.',build:'Three 20-second edits from the same footage.',criteria:'The emotional difference is obvious without changing the story.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Cuts & Transitions 101','https://www.youtube.com/watch?v=OAH0MoAv2CI','Watch'),k('Editing chapter — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'f6',title:'Attention',tag:'Psychology',why:'Editing directs the viewer’s eye and predicts what they will notice next.',learn:'Study visual hierarchy, anticipation, contrast, reaction shots, and information withholding.',practice:'STEP 1: Choose a 30-second sequence with a clear subject. STEP 2: Identify the exact moment you want the viewer to notice. STEP 3: Make one version using timing and shot order to guide attention. STEP 4: Make a second version that distracts from that moment. STEP 5: Ask someone to describe the first thing they noticed. PASS CHECK: the intended subject is noticed first in the controlled version.',build:'Create a 30-second attention-controlled edit.',criteria:'You can deliberately direct attention with timing and shot choice.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Joel & Ethan Coen — Shot | Reverse Shot','https://www.youtube.com/watch?v=5UE3jz_O_EM','Watch'),k('Memories of Murder — Ensemble Staging','https://www.youtube.com/watch?v=3Q3eITC01Fg','Practice')]},]},
{id:'story',title:'02 · Storytelling',subtitle:'Turn raw footage into meaning',lessons:[
{id:'s1',title:'Story beats',tag:'Story',why:'A good edit has progression, not just pretty shots.',learn:'Identify setup, escalation, turning point, payoff, and release.',practice:'STEP 1: Pick a 60–90 second video with a clear outcome. STEP 2: Watch once without pausing. STEP 3: Mark the first clear setup, escalation, turning point, payoff, and ending. STEP 4: Rewrite those beats as five short sentences. STEP 5: Find or shoot 8–12 clips and build your own 30–45 second version around those beats. PASS CHECK: another person can tell what changed from beginning to end.',build:'Edit a 45-second story with a clear beginning, middle, and end.',criteria:'The viewer can describe what changed.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('The Kuleshov Effect','https://www.youtube.com/watch?v=Vy2Vhnqtu8I','Watch'),k('Story Structure & Pacing','https://www.sabaoon.dev/courses/video-editing-techniques/01-story-structure-pacing','Read')]},
{id:'s2',title:'Motivated cuts',tag:'Craft',why:'Cuts feel natural when they are motivated by story, movement, sound, or attention.',learn:'Learn movement matches, gaze matches, sound bridges, and information cuts.',practice:'STEP 1: Collect 10–12 clips containing movement, looks, or related sounds. STEP 2: Pair five clips using matching movement or gaze. STEP 3: Pair two clips using audio rather than picture. STEP 4: Remove any cut that cannot be explained by story, movement, sound, or attention. STEP 5: Export a 30-second study and annotate each cut in a simple text note. PASS CHECK: every cut has a reason you can state in one sentence.',build:'A 30-second sequence where every cut has a reason.',criteria:'No random cuts.',resources:[k('Cuts & Transitions 101','https://www.youtube.com/watch?v=OAH0MoAv2CI','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'s3',title:'J-cuts and L-cuts',tag:'Craft',why:'Audio can connect scenes before or after the visual cut.',learn:'Understand J-cut, L-cut, dialogue overlap, and sound bridges.',practice:'STEP 1: Put two dialogue clips on the timeline. STEP 2: Create three J-cuts by starting the next audio before the picture. STEP 3: Create three L-cuts by carrying the previous audio into the next picture. STEP 4: Add one ambience or sound effect bridge. STEP 5: Compare each against hard cuts and keep the most natural versions. PASS CHECK: the scene flows without audio transitions calling attention to themselves.',build:'Edit a 45-second conversation using both.',criteria:'Audio transitions feel intentional.',resources:[k('J Cuts & L Cuts Explained','https://www.youtube.com/watch?v=wIw9CA-M0Ic','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('J-Cuts & L-Cuts — WeVideo Film School','https://www.wevideo.com/blog/j-cuts-l-cuts','Read')]},
{id:'s4',title:'B-roll as storytelling',tag:'Craft',why:'B-roll should add information, emotion, or context—not hide bad cuts.',learn:'Match B-roll to words, ideas, movement, and emotion.',practice:'STEP 1: Record or obtain a 30–45 second talking-head clip. STEP 2: Write down the key ideas spoken. STEP 3: Gather at least one useful B-roll shot for each idea. STEP 4: Cover only the words or moments that benefit from B-roll. STEP 5: Remove one B-roll shot that merely looks nice and adds no information. PASS CHECK: every B-roll shot either explains, proves, contrasts, or adds emotion.',build:'A 60-second B-roll-driven segment.',criteria:'Every B-roll shot adds something.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Cuts & Transitions 101','https://www.youtube.com/watch?v=OAH0MoAv2CI','Watch'),k('Editing Basics: Story Through Cuts and Music','https://tinymedialab.com/youtube-editing-basics-storytelling/','Read')]},
{id:'s5',title:'Montage',tag:'Story',why:'Montage compresses time and creates meaning through juxtaposition.',learn:'Study repetition, contrast, progression, and compression.',practice:'STEP 1: Gather 20–30 clips from one activity or process. STEP 2: Sort them into beginning, middle, and result. STEP 3: Build a 20-second rough montage using only cuts. STEP 4: Create a second version using contrast between shots. STEP 5: Add music only after the picture sequence works. PASS CHECK: the montage communicates a clear progression or idea even with the sound off.',build:'A 30-second montage with music and purposeful progression.',criteria:'The montage communicates a clear idea.',resources:[k('The Kuleshov Effect','https://www.youtube.com/watch?v=Vy2Vhnqtu8I','Watch'),k('Cuts & Transitions 101','https://www.youtube.com/watch?v=OAH0MoAv2CI','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'s6',title:'Emotional rhythm',tag:'Psychology',why:'Emotion changes when you change timing, reaction, sound, and shot order.',learn:'Study anticipation, release, silence, reaction, and contrast.',practice:'STEP 1: Choose one 15–20 second moment. STEP 2: Make a funny version using reaction and timing. STEP 3: Make a tense version using anticipation and tighter timing. STEP 4: Make an emotional version using reaction and silence. STEP 5: Do not change the core footage. PASS CHECK: each version produces a noticeably different emotional reading.',build:'Three versions of one 20-second scene.',criteria:'You can control emotional interpretation through editing.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Martin Scorsese — The Art of Silence','https://www.youtube.com/watch?v=NUrTRjEXjSM','Watch'),k('How to Edit Comedy','https://thecomedycrowd.com/how-to-edit-comedy/','Read')]},]},
{id:'audio',title:'03 · Audio',subtitle:'Make the edit feel professional through sound',lessons:[
{id:'a1',title:'Dialogue fundamentals',tag:'Audio',why:'Bad dialogue audio can destroy otherwise good video.',learn:'Learn levels, clipping, noise, EQ basics, and consistency.',practice:'STEP 1: Record or import one spoken clip with room noise. STEP 2: Create a duplicate before editing. STEP 3: Clean the clip, reduce obvious noise, and remove clipping or excessive peaks where possible. STEP 4: Adjust the level so the speech stays consistently comfortable. STEP 5: Compare before/after at normal listening volume. PASS CHECK: words are clear and no section suddenly becomes painfully loud or quiet.',build:'A 60-second dialogue edit with consistent volume.',criteria:'Speech is clear and comfortable.',resources:[k('How to SOUND DESIGN a Video — Step-By-Step','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Audio Effects','https://docs.kdenlive.org/en/effects_and_filters/audio_effects.html','Read')]},
{id:'a2',title:'Room tone',tag:'Audio',why:'Room tone prevents cuts from sounding like audio gaps.',learn:'Capture and use consistent ambient sound.',practice:'STEP 1: Find a quiet 10–15 second section from the same recording environment. STEP 2: Place the room tone on its own audio track. STEP 3: Cut dialogue into three edits. STEP 4: Fill the gaps with room tone and use short fades. STEP 5: Listen only to the edit points with headphones. PASS CHECK: the three dialogue cuts no longer expose abrupt background changes.',build:'A seamless conversation scene.',criteria:'Dialogue cuts do not expose silence.',resources:[k('How to SOUND DESIGN a Video — Step-By-Step','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Audio Effects','https://docs.kdenlive.org/en/effects_and_filters/audio_effects.html','Read')]},
{id:'a3',title:'Music as structure',tag:'Audio',why:'Music can control expectation and energy.',learn:'Use intro, build, drop, accent, and ending intentionally.',practice:'STEP 1: Choose one 30–45 second video sequence and one legal music track. STEP 2: Mark the track’s intro, build, strongest beat, and ending. STEP 3: Align three important picture changes to those musical moments. STEP 4: Make a second version where cuts ignore the beat. STEP 5: Compare which version feels more controlled and why. PASS CHECK: the music supports the edit’s structure instead of forcing every cut to land on a beat.',build:'A 45-second edit where music controls pacing.',criteria:'Cuts respond to musical structure without becoming predictable.',resources:[k('How to SOUND DESIGN a Video — Step-By-Step','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Editing Basics: Story Through Cuts and Music','https://tinymedialab.com/youtube-editing-basics-storytelling/','Read')]},
{id:'a4',title:'Sound effects',tag:'Audio',why:'Small sounds create realism and emphasis.',learn:'Use whooshes, impacts, ambience, foley, and UI sounds sparingly.',practice:'STEP 1: Start with a 20–30 second video with weak or no sound design. STEP 2: Add ambience first. STEP 3: Add only five intentional effects: movement, impact, interaction, transition, and one detail sound. STEP 4: Mute the music and judge whether the effects still improve the scene. STEP 5: Remove the weakest two effects. PASS CHECK: the final version feels richer, not busier.',build:'A 30-second sound-designed edit.',criteria:'Effects support the story instead of distracting.',resources:[k('How to SOUND DESIGN a Video — Step-By-Step','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Audio Effects','https://docs.kdenlive.org/en/effects_and_filters/audio_effects.html','Read')]},
{id:'a5',title:'Silence',tag:'Audio',why:'Silence creates contrast and gives important moments weight.',learn:'Use silence as a deliberate editing tool.',practice:'STEP 1: Choose a 20–30 second dramatic or emotional moment. STEP 2: Build a normal version with continuous music/ambience. STEP 3: Remove sound immediately before the key moment. STEP 4: Let the silence last long enough to be felt, then bring sound back deliberately. STEP 5: Compare the versions at normal volume. PASS CHECK: silence increases attention instead of feeling like an accidental audio problem.',build:'A 30-second dramatic sequence with controlled silence.',criteria:'Silence feels intentional.',resources:[k('Martin Scorsese — The Art of Silence','https://www.youtube.com/watch?v=NUrTRjEXjSM','Watch'),k('How to SOUND DESIGN a Video — Step-By-Step','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('The Art of Silence — Every Frame a Painting','https://www.youtube.com/watch?v=NUrTRjEXjSM','Watch')]},
{id:'a6',title:'Mixing',tag:'Audio',why:'A professional mix makes dialogue, music, and effects coexist.',learn:'Learn gain staging, ducking, fades, and basic balance.',practice:'STEP 1: Create three tracks: dialogue, music, effects. STEP 2: Balance dialogue first with music muted. STEP 3: Bring music in quietly and lower it under speech. STEP 4: Add effects one at a time. STEP 5: Listen once on headphones and once on laptop speakers. STEP 6: Fix any element that suddenly dominates. PASS CHECK: dialogue remains intelligible without music or effects disappearing completely.',build:'A 60-second polished mix.',criteria:'Dialogue remains understandable over music.',resources:[k('How to SOUND DESIGN a Video — Step-By-Step','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Audio Mixer','https://docs.kdenlive.org/en/user_interface/audio_mixer.html','Read')]},]},
{id:'visual',title:'04 · Visual Language',subtitle:'Color, motion, composition, and visual continuity',lessons:[
{id:'v1',title:'Composition for editors',tag:'Visual',why:'Editors inherit composition decisions and can reinforce them through timing and cropping.',learn:'Study framing, leading lines, negative space, balance, and visual hierarchy.',practice:'STEP 1: Screenshot 20 strong frames from films or videos. STEP 2: For each frame mark the main subject, supporting subject, and unused space. STEP 3: Recreate five frames using crops from your own footage. STEP 4: Make one intentionally unbalanced version. STEP 5: Compare how the eye moves through each image. PASS CHECK: you can explain the visual hierarchy of at least 15 of the 20 frames.',build:'A sequence where every shot has deliberate framing.',criteria:'You can explain the visual hierarchy.',resources:[k('Joel & Ethan Coen — Shot | Reverse Shot','https://www.youtube.com/watch?v=5UE3jz_O_EM','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'v2',title:'Color correction',tag:'Color',why:'Correction makes footage consistent before style is added.',learn:'Exposure, white balance, contrast, saturation, skin tones.',practice:'STEP 1: Place three mismatched clips next to each other. STEP 2: Correct exposure first. STEP 3: Match white balance. STEP 4: Match contrast and saturation conservatively. STEP 5: Compare all three on the timeline, not one clip at a time. STEP 6: Export a before/after comparison. PASS CHECK: the clips look like they belong in the same scene before any creative grade is added.',build:'A corrected 30-second sequence.',criteria:'Shots look like they belong together.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive — Introduction to Scopes','https://www.youtube.com/watch?v=f6VHlOZutm8','Watch'),k('Kdenlive Color Image Correction','https://docs.kdenlive.org/en/effects_and_filters/video_effects/color_image_correction.html','Read')]},
{id:'v3',title:'Color grading',tag:'Color',why:'A grade supports mood after technical correction.',learn:'Separate correction from creative look.',practice:'STEP 1: Start with already corrected footage. STEP 2: Make a neutral reference version. STEP 3: Create a warm version and a cool version. STEP 4: Keep skin tones believable unless a deliberate stylized choice is required. STEP 5: Watch each version muted and with sound to judge the visual mood alone. STEP 6: Choose the version that best supports the story. PASS CHECK: the creative look is intentional and does not hide technical inconsistencies.',build:'A 30-second stylized sequence.',criteria:'The look supports the story.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('LUTs Made Easy — Kdenlive','https://www.youtube.com/watch?v=F1h6Kg-WLDE','Watch'),k('Kdenlive Color Image Correction','https://docs.kdenlive.org/en/effects_and_filters/video_effects/color_image_correction.html','Read')]},
{id:'v4',title:'Speed and time',tag:'Motion',why:'Speed changes emphasis and perceived energy.',learn:'Understand slow motion, speed ramps, freeze frames, and time compression.',practice:'STEP 1: Choose one action clip with clear movement. STEP 2: Duplicate it three times. STEP 3: Create normal speed, slow-motion, and accelerated versions. STEP 4: Add one motivated speed change at a story beat rather than randomly. STEP 5: Create one freeze-frame or pause for emphasis. PASS CHECK: each speed change communicates a different purpose: clarity, energy, anticipation, or emphasis.',build:'A 30-second dynamic sequence.',criteria:'Speed changes are motivated.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive — Time Remapping','https://www.youtube.com/watch?v=f6VHlOZutm8','Watch'),k('Kdenlive effects and filters','https://docs.kdenlive.org/en/effects_and_filters.html','Read')]},
{id:'v5',title:'Motion and keyframes',tag:'Motion',why:'Keyframes create controlled movement and emphasis.',learn:'Position, scale, opacity, and smooth animation.',practice:'STEP 1: Put one clip on the timeline. STEP 2: Animate scale from 100% to a modest push-in. STEP 3: Animate position to follow a subject. STEP 4: Animate opacity for one controlled reveal. STEP 5: Adjust interpolation so the motion does not start or stop abruptly. STEP 6: Delete one animation that feels decorative instead of useful. PASS CHECK: every animation has a clear visual purpose and feels smooth.',build:'A 20-second motion sequence.',criteria:'Motion starts/stops naturally.',resources:[k('Keyframe Animation — Kdenlive','https://www.youtube.com/watch?v=M8hC5FbIzdE','Watch'),k('Keyframe Interpolation — Kdenlive','https://www.youtube.com/watch?v=F1h6Kg-WLDE','Watch'),k('Kdenlive effects and filters','https://docs.kdenlive.org/en/effects_and_filters.html','Read')]},
{id:'v6',title:'Visual continuity',tag:'Craft',why:'Color, motion, screen direction, and composition should not accidentally fight each other.',learn:'Match direction, brightness, color, lens feel, and movement.',practice:'STEP 1: Build a six-shot sequence with intentionally mismatched clips. STEP 2: Identify five continuity problems. STEP 3: Fix one category at a time: direction, brightness, color, scale, movement. STEP 4: Watch the sequence full-screen without pausing. STEP 5: Write down the remaining visual distraction. PASS CHECK: the viewer can follow the scene without being pulled out by accidental mismatches.',build:'A seamless multi-shot sequence.',criteria:'Visual changes feel intentional.',resources:[k('Joel & Ethan Coen — Shot | Reverse Shot','https://www.youtube.com/watch?v=5UE3jz_O_EM','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Effects and Filters','https://docs.kdenlive.org/en/effects_and_filters.html','Read')]},]},
{id:'kdenlive',title:'05 · Kdenlive',subtitle:'Turn editing knowledge into repeatable software skill',lessons:[
{id:'k1',title:'Project setup',tag:'Kdenlive',why:'Correct project settings prevent technical problems later.',learn:'Project folders, profiles, frame rate, resolution, and assets.',practice:'STEP 1: Create a project folder with folders for Footage, Audio, Graphics, Project, Exports. STEP 2: Open Kdenlive and choose a profile that matches the footage. STEP 3: Import media and organize it in the project bin. STEP 4: Save the project into the Project folder. STEP 5: Close and reopen it to verify the structure. PASS CHECK: you can start a new project from the same structure without guessing where files belong.',build:'A reusable project template.',criteria:'You can start a project without guessing settings.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Learn Kdenlive in 30 Minutes','https://www.youtube.com/watch?v=f6VHlOZutm8','Watch'),k('Kdenlive Quick Start','https://docs.kdenlive.org/en/getting_started/quickstart.html','Read'),k('Kdenlive Getting Started','https://docs.kdenlive.org/en/getting_started.html','Read')]},
{id:'k2',title:'Timeline mastery',tag:'Kdenlive',why:'Timeline fluency is where editing speed comes from.',learn:'Selection, razor, spacer, ripple, tracks, snapping, and keyboard workflow.',practice:'STEP 1: Import 10–15 clips. STEP 2: Do a 60-second rough cut using the timeline keyboard workflow. STEP 3: Practice selection, razor, spacer, ripple, snapping, and track targeting. STEP 4: Repeat the same edit while reducing mouse travel. STEP 5: Time the second attempt. PASS CHECK: the second attempt is faster without lowering story quality, and you can explain what each tool changed.',build:'A fast rough cut.',criteria:'You can navigate and cut confidently.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Learn Kdenlive in 30 Minutes','https://www.youtube.com/watch?v=f6VHlOZutm8','Watch'),k('Kdenlive Editing','https://docs.kdenlive.org/en/cutting_and_assembling/editing.html','Read')]},
{id:'k3',title:'Transitions and compositions',tag:'Kdenlive',why:'Transitions should solve a visual problem or create a deliberate feeling.',learn:'Mixes, dissolves, wipes, compositions, and when not to use them.',practice:'STEP 1: Build three hard-cut transitions between shots. STEP 2: Recreate the same three changes using a dissolve/mix, a wipe, and a layered composition. STEP 3: Decide which version best serves the story. STEP 4: Remove every transition that has no clear purpose. STEP 5: Export the final 30-second study. PASS CHECK: at least two transitions are removed because the hard cut works better.',build:'A 30-second transition study.',criteria:'You choose transitions intentionally.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Tutorials — transitions and animation','https://www.youtube.com/watch?v=f6VHlOZutm8','Watch'),k('Kdenlive Transitions and Compositions','https://docs.kdenlive.org/en/compositing/transitions.html','Read'),k('Kdenlive Video Tutorials','https://docs.kdenlive.org/en/getting_started/tutorials/video_tutorials.html','Watch')]},
{id:'k4',title:'Masks and blending',tag:'Kdenlive',why:'Compositing expands what simple cuts can do.',learn:'Alpha, masks, blending, and selective effects.',practice:'STEP 1: Put a foreground clip above a background clip. STEP 2: Create a mask around one object or region. STEP 3: Feather the edge so it blends naturally. STEP 4: Animate the mask or subject for a few seconds. STEP 5: Try one blend/composite mode and compare it with a normal layer. PASS CHECK: the composite edges remain believable while the subject moves.',build:'A simple masked composite.',criteria:'Mask edges and timing are controlled.',resources:[k('Object Mask — Kdenlive','https://www.youtube.com/watch?v=9PTqvcRobUw','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Video Tutorials','https://docs.kdenlive.org/en/getting_started/tutorials/video_tutorials.html','Watch'),k('Kdenlive Effects and Filters','https://docs.kdenlive.org/en/effects_and_filters.html','Read')]},
{id:'k5',title:'Titles and subtitles',tag:'Kdenlive',why:'Readable graphics improve communication.',learn:'Hierarchy, safe areas, timing, subtitles, and lower thirds.',practice:'STEP 1: Create a title that introduces a person or topic. STEP 2: Use one font family and two text sizes at most. STEP 3: Build one lower third with a name and role. STEP 4: Create one subtitle style and apply it to 10–15 seconds of dialogue. STEP 5: Check readability on both the main preview and a small window. PASS CHECK: text is readable quickly and does not fight the footage.',build:'A branded title package.',criteria:'Text is readable and consistent.',resources:[k('How to add text to video — Kdenlive','https://www.youtube.com/watch?v=9PTqvcRobUw','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Titles and Graphics','https://docs.kdenlive.org/en/titles_and_graphics/titles_and_graphics.html','Read')]},
{id:'k6',title:'Effects discipline',tag:'Kdenlive',why:'Professional editing is not effect stacking.',learn:'Choose effects based on story, polish, and problem solving.',practice:'STEP 1: Take a plain 20-second edit. STEP 2: Add effects until it feels obviously overdone. STEP 3: Create a duplicate and remove half the effects. STEP 4: For every remaining effect, write the problem it solves or the feeling it creates. STEP 5: Remove anything you cannot justify. PASS CHECK: the restrained version looks more intentional than the overloaded version.',build:'A restrained polished edit.',criteria:'Every effect has a reason.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Learn Kdenlive in 30 Minutes','https://www.youtube.com/watch?v=f6VHlOZutm8','Watch'),k('Kdenlive Effects and Filters','https://docs.kdenlive.org/en/effects_and_filters.html','Read')]},
{id:'k7',title:'Proxy workflow for low-end PCs',tag:'Performance',why:'Your Toshiba needs an editing workflow designed around its limits.',learn:'Proxy clips, preview rendering, and lightweight project settings.',practice:'STEP 1: Start with a 1080p or higher project containing several demanding clips. STEP 2: Test playback before proxies and note where it stutters. STEP 3: Enable proxy generation and choose a practical proxy size. STEP 4: Generate proxies and repeat the same timeline test. STEP 5: Use preview rendering where necessary. STEP 6: Record the settings that give the best balance on your PC. PASS CHECK: you can complete a real edit without repeatedly stopping because of playback.',build:'A 1080p project that remains workable on your PC.',criteria:'You can edit without constant playback frustration.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Learn Kdenlive in 30 Minutes','https://www.youtube.com/watch?v=f6VHlOZutm8','Watch'),k('Kdenlive Proxy Clips','https://docs.kdenlive.org/en/project_and_asset_management/project_settings/proxy_settings.html','Read'),k('Kdenlive Installation / System Requirements','https://docs.kdenlive.org/en/getting_started/installation.html','Read')]},
{id:'k8',title:'Export and delivery',tag:'Kdenlive',why:'A great edit still fails if the final file is wrong.',learn:'Codecs, containers, resolution, frame rate, bitrate, and platform exports.',practice:'STEP 1: Finish a 30–60 second edit. STEP 2: Export a high-quality master using the project frame rate and resolution. STEP 3: Export a second version for vertical/social use when appropriate. STEP 4: Rename files using ProjectName_Version_Date. STEP 5: Watch the entire exported file, not just the timeline. STEP 6: Check audio, spelling, black frames, sync, and final duration. PASS CHECK: both files play correctly outside Kdenlive and match the intended delivery format.',build:'A delivery folder with clean filenames.',criteria:'You can deliver platform-ready files without guessing.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('How to Render 1080p Video in Kdenlive 2025','https://www.youtube.com/watch?v=9PTqvcRobUw','Watch'),k('Kdenlive Exporting','https://docs.kdenlive.org/en/exporting.html','Read')]},]},
{id:'projects',title:'06 · Project Lab',subtitle:'Projects are the proof that the skills are real',lessons:[
{id:'p1',title:'Project 01 — Cinematic 30s',tag:'Project',why:'A short project forces you to practice shot choice and rhythm.',learn:'Review pacing, motivated cuts, music, and color.',practice:'STEP 1: Gather 15–25 clips around one subject or activity. STEP 2: Create selects before opening the final edit. STEP 3: Build a 30-second rough cut using only cuts. STEP 4: Add music and shape pacing around musical structure. STEP 5: Correct color and mix audio. STEP 6: Export and watch on a second device. PASS CHECK: strong opening, no random cuts, controlled audio, and a coherent visual treatment.',build:'A polished 30-second cinematic sequence.',criteria:'Strong opening, intentional cuts, controlled audio, coherent grade.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Video Tutorials','https://docs.kdenlive.org/en/getting_started/tutorials/video_tutorials.html','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'p2',title:'Project 02 — Talking-head YouTube',tag:'Project',why:'Talking-head editing is a practical freelance skill.',learn:'Dialogue cleanup, jump cuts, B-roll, captions, and pacing.',practice:'STEP 1: Import 5–10 minutes of talking-head footage. STEP 2: Create a selects sequence. STEP 3: Build the story without graphics first. STEP 4: Clean dialogue and use J/L cuts. STEP 5: Add B-roll only where it improves information or pacing. STEP 6: Add captions/lower thirds and a final audio mix. PASS CHECK: the viewer can follow the speaker comfortably without distracting edits.',build:'A 3–5 minute YouTube segment.',criteria:'Clear story, clean audio, purposeful B-roll.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('J Cuts & L Cuts Explained','https://www.youtube.com/watch?v=wIw9CA-M0Ic','Watch'),k('Kdenlive Audio Effects','https://docs.kdenlive.org/en/effects_and_filters/audio_effects.html','Read')]},
{id:'p3',title:'Project 03 — Tech tutorial',tag:'Project',why:'This connects editing with your tech interests and future channel.',learn:'Screen recordings, callouts, zooms, cursor emphasis, and voiceover.',practice:'STEP 1: Write a tiny tutorial with 3–5 steps. STEP 2: Record screen footage and voiceover. STEP 3: Build the explanation with a clear sequence of actions. STEP 4: Add restrained zooms/callouts only where the viewer needs attention. STEP 5: Add captions or key labels. STEP 6: Test the finished video by following the instructions yourself. PASS CHECK: a first-time viewer can perform the demonstrated steps without asking what to click next.',build:'A 4–6 minute tech tutorial.',criteria:'Viewer can follow every step.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive — Pan and Zoom','https://www.youtube.com/watch?v=B8ZPoWaxQrA','Watch'),k('Kdenlive Video Tutorials','https://docs.kdenlive.org/en/getting_started/tutorials/video_tutorials.html','Watch')]},
{id:'p4',title:'Project 04 — Short-form pack',tag:'Project',why:'Short-form work teaches fast hooks and retention.',learn:'Hooks, pattern interrupts, captions, pacing, and vertical delivery.',practice:'STEP 1: Choose one 2–5 minute source video. STEP 2: Find three possible hooks from the strongest idea. STEP 3: Build three 20–30 second versions with different openings. STEP 4: Keep the central information but vary pacing, captions, and visual interruption. STEP 5: Export vertical versions. STEP 6: Compare the first three seconds of all versions. PASS CHECK: every version communicates the topic immediately and reaches a clear payoff.',build:'Three short-form videos from one source.',criteria:'Each has a clear hook and payoff.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Cuts & Transitions 101','https://www.youtube.com/watch?v=OAH0MoAv2CI','Watch'),k('Editing Basics: Story Through Cuts and Music','https://tinymedialab.com/youtube-editing-basics-storytelling/','Read')]},
{id:'p5',title:'Project 05 — Product promo',tag:'Project',why:'Commercial-style editing develops visual polish and client value.',learn:'Product shots, rhythm, typography, sound design, and CTA.',practice:'STEP 1: Choose one simple product. STEP 2: Plan a 30–45 second sequence with hook, product reveal, three benefits/details, and CTA. STEP 3: Shoot or collect wide/detail/action shots. STEP 4: Edit for rhythm before adding graphics. STEP 5: Add restrained typography and sound effects. STEP 6: Review the final five seconds and make the CTA unmistakable. PASS CHECK: the viewer understands what the product is, why it matters, and what to do next.',build:'A 30–45 second promo.',criteria:'Clear product value and polished presentation.',resources:[k('How to SOUND DESIGN a Video — Step-By-Step','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Titles and Graphics','https://docs.kdenlive.org/en/titles_and_graphics/titles_and_graphics.html','Read')]},
{id:'p6',title:'Project 06 — Mini documentary',tag:'Project',why:'Documentary editing tests story judgment with imperfect footage.',learn:'Interview structure, B-roll, narration, archival material, and pacing.',practice:'STEP 1: Choose a person, place, process, or small story. STEP 2: Transcribe or note the strongest interview statements. STEP 3: Create a paper edit with beginning, development, and ending before opening Kdenlive. STEP 4: Build the interview spine first. STEP 5: Cover gaps with purposeful B-roll and ambience. STEP 6: Remove information that repeats without advancing the story. PASS CHECK: the documentary has a clear central question or idea and does not rely on narration to explain every cut.',build:'A 3–5 minute mini documentary.',criteria:'The story works without explaining it verbally.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Kdenlive Video Tutorials','https://docs.kdenlive.org/en/getting_started/tutorials/video_tutorials.html','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},]},
{id:'pro',title:'07 · Professional Workflow',subtitle:'Learn to work like an editor, not just use an editor',lessons:[
{id:'r1',title:'Read a brief',tag:'Pro',why:'Clients pay for outcomes, not software knowledge.',learn:'Extract audience, message, platform, tone, deadline, and deliverables.',practice:'STEP 1: Write a fake client request for a 60-second social video. STEP 2: Convert the request into audience, goal, message, tone, platform, deadline, assets, and deliverables. STEP 3: Write five questions you would ask before editing. STEP 4: Turn the answers into an edit checklist. STEP 5: Do not open Kdenlive until the checklist is complete. PASS CHECK: the brief tells you what success looks like and what is out of scope.',build:'A one-page edit brief.',criteria:'You can define the job before touching footage.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('This Guy Edits — creative editing and professional practice','https://thisguyedits.com/','Read')]},
{id:'r2',title:'Selects before polish',tag:'Pro',why:'Professional speed comes from decisions before effects.',learn:'Organize footage, label selects, and build a paper/rough edit.',practice:'STEP 1: Import a folder containing at least 20 clips. STEP 2: Sort clips into useful categories. STEP 3: Mark selects with clear names or markers. STEP 4: Build a selects sequence before adding effects. STEP 5: Write a three-sentence summary of the story before polishing. PASS CHECK: another editor could open the project and understand what footage is important.',build:'A structured project bin + selects sequence.',criteria:'You know what the edit is before polishing.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('This Guy Edits — Editing = Story, Character, Emotion','https://thisguyedits.com/','Read')]},
{id:'r3',title:'Rough cut → fine cut',tag:'Pro',why:'Trying to perfect every shot immediately wastes time.',learn:'Separate story, pacing, polish, graphics, and final QC passes.',practice:'STEP 1: Create a rough cut with no effects or fancy graphics. STEP 2: Review only structure and remove weak material. STEP 3: Make a second pass for pacing and transitions. STEP 4: Make a third pass for audio, color, and graphics. STEP 5: Export each stage with a clear version name. PASS CHECK: each pass solves a different class of problem and the final pass does not secretly rewrite the whole story.',build:'Rough, fine, and final versions of one project.',criteria:'Each pass has a different purpose.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('Editing — Moving Pictures','https://uark.pressbooks.pub/movingpictures/chapter/editing/','Read')]},
{id:'r4',title:'Revision workflow',tag:'Pro',why:'Client revisions are normal; chaos is optional.',learn:'Versioning, notes, timecodes, scope, and change tracking.',practice:'STEP 1: Export a version 1 of a project. STEP 2: Write 10 realistic revision notes with timecodes. STEP 3: Group notes by story, audio, visual, and text. STEP 4: Process them from largest impact to smallest. STEP 5: Save a new version instead of overwriting the original. STEP 6: Recheck every note after export. PASS CHECK: every requested change is either completed, documented as impossible, or identified as outside scope.',build:'A versioned delivery workflow.',criteria:'You can revise without breaking the project.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('This Guy Edits — creative editing practice','https://thisguyedits.com/','Read')]},
{id:'r5',title:'Portfolio reel',tag:'Pro',why:'A portfolio should demonstrate outcomes quickly.',learn:'Select only work that represents your target service.',practice:'STEP 1: Choose 5–8 of your strongest shots or mini-project moments. STEP 2: Remove anything that is merely flashy but weak. STEP 3: Put the strongest proof in the first 5–10 seconds. STEP 4: Keep the reel short and focused on one service direction. STEP 5: Add simple name/contact information at the end. PASS CHECK: a stranger can identify the type and quality of editing offered within 10 seconds.',build:'Your first editing portfolio page/reel.',criteria:'A stranger understands what you can edit within 10 seconds.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('This Guy Edits — Editing = Story, Character, Emotion','https://thisguyedits.com/','Read')]},
{id:'r6',title:'Delivery checklist',tag:'Pro',why:'Reliability is a professional skill.',learn:'Check audio, black frames, spelling, captions, exports, filenames, and backups.',practice:'STEP 1: Create a checklist with picture, audio, text, export, file naming, and backup sections. STEP 2: Run the checklist on your latest project from start to finish. STEP 3: Watch the exported file outside Kdenlive. STEP 4: Check it once normally and once while actively hunting errors. STEP 5: Store the checklist so every future project can reuse it. PASS CHECK: the project has no avoidable technical errors when delivered.',build:'Reusable delivery checklist.',criteria:'You catch technical mistakes before delivery.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('How to SOUND DESIGN a Video — Step-By-Step','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('Kdenlive Exporting','https://docs.kdenlive.org/en/exporting.html','Read')]},]},
{id:'money',title:'08 · Money Path',subtitle:'Turn editing ability into a small, repeatable service',lessons:[
{id:'m1',title:'Pick an offer',tag:'Money',why:'A clear service is easier to sell than “I edit videos.”',learn:'Choose one starting niche: shorts, YouTube, tech, podcasts, or promos.',practice:'STEP 1: List three services you could realistically deliver with your current skills. STEP 2: For each, define the target client and exact deliverable. STEP 3: Estimate how long one job would take. STEP 4: Pick the offer with the clearest result and manageable workload. STEP 5: Write one sentence: “I help X turn Y into Z.” PASS CHECK: someone outside editing can understand what is being sold without asking for a long explanation.',build:'One clear starter offer.',criteria:'A client understands what they receive.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('This Guy Edits — creative editing','https://thisguyedits.com/','Read')]},
{id:'m2',title:'Build a sample package',tag:'Money',why:'Samples prove your service before a client trusts you.',learn:'Package 3–5 relevant examples with before/after context.',practice:'STEP 1: Choose one target service from the previous lesson. STEP 2: Make 3–5 samples specifically for that service. STEP 3: For each sample, show the problem, the edit, and the result. STEP 4: Put files in one clean portfolio folder. STEP 5: Write a two-sentence description for each piece. PASS CHECK: a prospect can judge the service without needing a long explanation.',build:'Starter portfolio + service description.',criteria:'A prospect can evaluate you without a long explanation.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('This Guy Edits — Editing = Story, Character, Emotion','https://thisguyedits.com/','Read')]},
{id:'m3',title:'Find prospects',tag:'Money',why:'Income comes from consistent outreach and useful relationships.',learn:'Identify creators, small businesses, tech channels, and local brands.',practice:'STEP 1: Choose one niche and one service. STEP 2: Build a list of 20 realistic prospects who already publish video. STEP 3: For each prospect, note one specific improvement an editor could make. STEP 4: Write a short personalized message that points to that improvement. STEP 5: Track date, contact, response, and next action in a simple sheet. PASS CHECK: you have a repeatable prospecting routine rather than waiting for random opportunities.',build:'A simple outreach tracker.',criteria:'You have a repeatable prospecting process.',resources:[k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('This Guy Edits — professional editing practice','https://thisguyedits.com/','Read')]},
{id:'m4',title:'Price scope, not hope',tag:'Money',why:'Clear scope prevents undercharging and endless revisions.',learn:'Define deliverables, turnaround, revisions, and extras.',practice:'STEP 1: Choose one editing service. STEP 2: Define exactly what is included in a starter package. STEP 3: Set a turnaround time and revision limit. STEP 4: List add-ons separately. STEP 5: Create three scope levels without changing the basic service outcome. STEP 6: Test whether a client could compare the packages without needing a call. PASS CHECK: scope, deadline, revisions, and extras are all explicit.',build:'A simple rate card.',criteria:'You can explain exactly what is included.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('How Does an Editor Think and Feel?','https://www.youtube.com/watch?v=3Q3eITC01Fg','Watch'),k('This Guy Edits — editing workflow and professional practice','https://thisguyedits.com/','Read')]},
{id:'m5',title:'Repeatability',tag:'Money',why:'A service becomes sustainable when your process gets faster.',learn:'Templates, presets, checklists, project organization, and reusable assets.',practice:'STEP 1: Take one completed project and duplicate its structure as a template. STEP 2: Save useful title, audio, color, and export presets. STEP 3: Turn your delivery checks into a reusable checklist. STEP 4: Time how long it takes to prepare a new project from scratch. STEP 5: Repeat using the system and record the new time. PASS CHECK: the second project starts faster and with fewer forgotten steps than the first.',build:'Your first repeatable editing system.',criteria:'The second project can start faster than the first.',resources:[k('Kdenlive Tutorial for Beginners','https://www.youtube.com/watch?v=YnSE9qgGui4','Watch'),k('How to SOUND DESIGN a Video — Step-By-Step','https://www.youtube.com/watch?v=Wcxw3BPSt3A','Watch'),k('Kdenlive Quick Start','https://docs.kdenlive.org/en/getting_started/quickstart.html','Read')]},]},
]
export const allLessons=stages.flatMap(s=>s.lessons.map(l=>({...l,stageId:s.id,stageTitle:s.title})))
